  text-decoration: none;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
  outline: 3px solid #fff;
  outline-offset: 2px;
}

/* ── Page layout ─────────────────────────────────────────── */
.page-header {
  text-align: center;
  margin-bottom: 2rem;
}

.page-header h1 {
  font-size: clamp(1.6rem, 4vw, 2.25rem);
  font-weight: 800;
  letter-spacing: -.02em;
  color: var(--color-text);
}

.page-header p {
  color: var(--color-text-secondary);
  margin-top: .5rem;
  font-size: 1rem;
}

.quiz-form {
  max-width: 680px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ── Question card ────────────────────────────────────────── */
.form-field {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 1.75rem 2rem;
  border: 1.5px solid transparent;
  transition: border-color var(--transition);
}

.form-field:focus-within {
  border-color: var(--color-border-focus);
}

.question-meta {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin-bottom: .5rem;
}

.question-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.75rem;
  height: 1.75rem;
  background: var(--color-primary-light);
  color: var(--color-primary);
  font-size: .75rem;
  font-weight: 700;
  border-radius: 50%;
  flex-shrink: 0;
}

.form-field legend {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.4;
}

.help-text {
  font-size: .875rem;
  color: var(--color-text-secondary);
  margin-top: .375rem;
  margin-bottom: 1.25rem;
}

.choices {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: .625rem;
  margin-top: 1rem;
}

/* ── Custom checkbox ─────────────────────────────────────── */
.choice-label {
  display: flex;
  align-items: center;
  gap: .875rem;
  padding: .75rem 1rem;
  border-radius: var(--radius-sm);
  border: 1.5px solid var(--color-border);
  cursor: pointer;
  user-select: none;
  transition: background var(--transition), border-color var(--transition);
  font-size: .9375rem;
}

.choice-label:hover {
  background: var(--color-primary-light);
  border-color: var(--color-primary);
}

/* Real checkbox visually hidden, still focusable */
.choice-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

.choice-box {
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  border: 2px solid var(--color-border);
  border-radius: 4px;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition), border-color var(--transition);
}

.choice-box::after {
  content: "";
  display: block;
  width: .4rem;
  height: .65rem;
  border: 2.5px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg) translateY(-1px);
  opacity: 0;
  transition: opacity var(--transition);
}

/* Checked state driven by sibling selector via JS class on label */
.choice-label.is-checked {
  background: var(--color-primary-light);
  border-color: var(--color-primary);
}

.choice-label.is-checked .choice-box {
  background: var(--color-check-bg);
  border-color: var(--color-check-bg);
}

.choice-label.is-checked .choice-box::after {
  opacity: 1;
}

/* Focus ring on the label (triggered when input is focused) */
.choice-input:focus-visible + .choice-label {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
  box-shadow: var(--shadow-focus);
}

/* ── Error / validation ──────────────────────────────────── */
.field-error {
  display: none;
  align-items: center;
  gap: .375rem;
  font-size: .8125rem;
  color: var(--color-error);
  margin-top: .75rem;
  font-weight: 500;
}

.field-error svg {
  flex-shrink: 0;
}

.form-field[aria-invalid="true"] .field-error {
  display: flex;
}

.form-field[aria-invalid="true"] {
  border-color: var(--color-error);
}

/* ── Submit area ─────────────────────────────────────────── */
.form-footer {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: .75rem;
}

.submit-btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: var(--color-primary);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  padding: .75rem 2rem;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  /* Transparent outline for forced-colors */
  outline: 2px solid transparent;
  outline-offset: 2px;
}

.submit-btn:hover {
  background: var(--color-primary-hover);
}

.submit-btn:active {
  background: var(--color-primary-active);
  transform: scale(.98);
}

.submit-btn:focus-visible {
  outline: 3px solid var(--color-primary);
  box-shadow: var(--shadow-focus);
}

/* ── Result banner ───────────────────────────────────────── */
.result-banner {
  background: var(--color-success-light);
  border: 1.5px solid #bbf7d0;
  border-radius: var(--radius-md);
  padding: 1.25rem 1.5rem;
  color: var(--color-success);
  font-weight: 600;
  font-size: 1rem;
  display: none;
}

.result-banner.visible {
  display: block;
}

/* ── Forced colors ───────────────────────────────────────── */
@media (forced-colors: active) {
  .choice-label {
    border-color: ButtonBorder;
  }
  .choice-label.is-checked {
    border-color: Highlight;
    background: Canvas;
    color: CanvasText;
  }
  .choice-box {
    border-color: ButtonBorder;
    background: Canvas;
  }
  .choice-label.is-checked .choice-box {
    background: Highlight;
    border-color: Highlight;
  }
  .submit-btn {
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonBorder;
    forced-color-adjust: none;
  }
}

/* ── Reflow @ 320px ──────────────────────────────────────── */
@media (max-width: 400px) {
  .form-field {
    padding: 1.25rem 1rem;
  }
  .submit-btn {
    width: 100%;
    justify-content: center;
  }
  .form-footer {
    align-items: stretch;
  }
}
