(function () {
  const form = document.getElementById('quiz-form');
  const resultBanner = document.getElementById('result-banner');

  /* ── Sync visual checked state to label class ────────── */
  document.querySelectorAll('.choice-input').forEach(function (input) {
    const label = input.nextElementSibling;

    function syncState() {
      label.classList.toggle('is-checked', input.checked);
    }

    input.addEventListener('change', syncState);
    syncState(); // initialise
  });

  /* ── Validate: each fieldset needs ≥ 1 selection ─────── */
  function validateForm() {
    let isValid = true;
    const fieldsets = form.querySelectorAll('fieldset[data-required]');

    fieldsets.forEach(function (fieldset) {
      const anyChecked = fieldset.querySelector('.choice-input:checked') !== null;
      const wrapper = fieldset.closest('.form-field');

      if (!anyChecked) {
        wrapper.setAttribute('aria-invalid', 'true');
        isValid = false;
      } else {
        wrapper.removeAttribute('aria-invalid');
      }
    });

    return isValid;
  }

  /* ── Clear error on change ───────────────────────────── */
  form.querySelectorAll('.choice-input').forEach(function (input) {
    input.addEventListener('change', function () {
      const wrapper = input.closest('.form-field');
      if (input.checked) {
        wrapper.removeAttribute('aria-invalid');
      }
    });
  });

  /* ── Submit ──────────────────────────────────────────── */
  form.addEventListener('submit', function (e) {
    e.preventDefault();

    resultBanner.classList.remove('visible');

    const valid = validateForm();

    if (!valid) {
      // Focus the first invalid question
      const firstInvalid = form.querySelector('.form-field[aria-invalid="true"]');
      if (firstInvalid) {
        const firstInput = firstInvalid.querySelector('.choice-input');
        if (firstInput) firstInput.focus();
      }
      return;
    }

    // Build a summary of selected answers
    const answers = [];
    form.querySelectorAll('fieldset[data-required]').forEach(function (fieldset) {
      const legend = fieldset.querySelector('legend').textContent.trim();
      const selected = Array.from(fieldset.querySelectorAll('.choice-input:checked'))
        .map(function (cb) { return cb.closest('.choice-label').querySelector('.choice-text').textContent.trim(); });
      answers.push({ question: legend, selected: selected });
    });

    const score = answers.reduce(function (acc, a) {
      return acc + (a.selected.length > 0 ? 1 : 0);
    }, 0);

    resultBanner.textContent = '✓ Quiz submitted! You answered all ' + score + ' question' + (score !== 1 ? 's' : '') + '. Thanks for participating!';
    resultBanner.classList.add('visible');
    resultBanner.focus();
  });
})();
